Boolean prg_init( void )
{    
  prg_evt = os_evt_create(); 
	
	prg_reg = reg_table_create(REG_ATOMIC_USE_RES); 

	prg_menu = 0 ;

	prg_exit = FALSE ; 
        
  //prg_use_door = FALSE ;//was assigned in the body_preinit() of intl_port_init already!
	
	return TRUE ; 
}

//--------------------------------------------------------------------------//
void  set_prg_use_door(Boolean ctrl)
{
	
	prg_use_door = ctrl ? TRUE : FALSE;
}

